import{_ as a,o as i,c as t,ag as s}from"./chunks/framework.Drp2S_UI.js";const k=JSON.parse('{"title":"T20：只保留 HarfBuzz 排版","description":"","frontmatter":{},"headers":[],"relativePath":"guide/native-only-engine.md","filePath":"guide/native-only-engine.md","lastUpdated":1792653875000}'),n={name:"guide/native-only-engine.md"};function l(r,e,o,d,p,c){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="t20-只保留-harfbuzz-排版" tabindex="-1">T20：只保留 HarfBuzz 排版 <a class="header-anchor" href="#t20-只保留-harfbuzz-排版" aria-label="Permalink to &quot;T20：只保留 HarfBuzz 排版&quot;">​</a></h1><p>T20 删除了旧文字引擎的实现及切换入口。正文、表格单元格、控件、列表标记、 页眉页脚、页码、水印和图片说明文字统一使用 HarfBuzz；图片、公式、表格、 分隔符、分页符、复选框、单选框和 Block 继续使用各自的原生对象布局与绘制。</p><h2 id="删除范围" tabindex="-1">删除范围 <a class="header-anchor" href="#删除范围" aria-label="Permalink to &quot;删除范围&quot;">​</a></h2><ul><li>删除 <code>BrowserTextShaper</code>、<code>TextParticle</code>、<code>IncrementalRowComputer</code>，以及 Draw 中逐元素测宽、断行、对齐与续算的旧主循环。</li><li>删除 <code>forceLegacy</code>、resume/旧增量行状态、旧 RTL 告警、旧布局字段清理回退、 控件 minWidth 旧行补位循环和列表浏览器测宽。</li><li>删除失去调用者的旧表格递归布局编排、FlowConstraints、BlockMeasure 和旧行盒策略。 表格行列几何查询、镜像坐标等仍有对象消费方的工具保留。</li><li>删除旧分页回退循环。分页依赖原生 DocumentFlow 放置结果，连续页使用原生行高度。</li><li>删除超链接、标签、上下标的浏览器文字绘制方法；保留超链接交互、标签背景和 上下标装饰偏移。删除留痕中对浏览器字体基准测量的依赖。</li><li>删除 <code>TextEngineMode</code>、<code>RenderMode</code> 枚举、导出及配置字段，不再存在运行时引擎选择。</li><li>位置与表格分片只读取原生节点，禁止退回文档元素上的 metrics/visualLeft 字段。</li></ul><p><code>IRow</code>/行快照仍是 T19 保留的独立兼容查询输出，按原生几何即时生成、深克隆； 它们不参与排版、缓存、绘制或编辑。旧增量算法的行快照和 resume 类型已经删除。 这是输出兼容边界，并非另一个渲染引擎。</p><h2 id="初始化和旧配置" tabindex="-1">初始化和旧配置 <a class="header-anchor" href="#初始化和旧配置" aria-label="Permalink to &quot;初始化和旧配置&quot;">​</a></h2><p>默认构造也必须等待字体及 WASM 初始化：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> editor</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Editor.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(container, data, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  autoDownloadFonts: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">})</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 或 new Editor(...) 后 await editor.ready</span></span></code></pre></div><p>JavaScript 调用方只要传入 <code>textEngine</code> 或 <code>renderMode</code>（即使值为 undefined）， 就会收到 TypeError，提示移除该选项并等待 <code>editor.ready</code>。TypeScript 配置接口和 包导出已删除这两个选择器。初始化失败按现有 ready/state/error 协议报告； 缺字沿用字体下载/诊断/占位流程，不再启用浏览器文字回退。</p><p>HarfBuzz 的一个逻辑簇可能产生多个字形。兼容光标适配器将同簇字形几何合并， 避免阿拉伯字母附加字形造成重复光标停靠点；保留逻辑索引与视觉移动语义。</p><h2 id="验证与迁移边界" tabindex="-1">验证与迁移边界 <a class="header-anchor" href="#验证与迁移边界" aria-label="Permalink to &quot;验证与迁移边界&quot;">​</a></h2><ul><li>TypeScript、ESLint、ESM 库构建及包消费检查通过。</li><li>定向 Vitest：24 个文件、171 个用例，覆盖初始化、原生布局、字体整形、对象、 控件、交互、模型隔离及增量差分。</li><li>Electron 定向覆盖 10 个规格文件、53 个用例：环绕分栏、跨页表格、对象及 iframe 打印、双向交互、控件、辅助文字、正文及表格增量布局，以及 Worker 序列化和打印基线。</li><li>新增 native-only 契约测试：默认初始化和编辑禁止 Canvas measureText/fillText/ strokeText；扫描生产源码，防止恢复旧实现、模式开关或浏览器文字绘制。</li><li>原 BrowserTextShaper 测试改用真实 HarfBuzz 及固定字体，按逻辑簇而非字形数量 验证交互；旧增量行算法及旧 RTL 提示测试随实现删除。</li><li>T01 快照和 T10 几何 JSON 保持不变，并增加 SHA-256 校验。可执行基线迁入 <code>native-baseline.test.ts</code>，检查原生几何和语义；历史快照不再要求旧算法运行。</li><li>对象和控件的浏览器断言改读 position.metrics，不再读取文档模型上的瞬态字段。</li><li>浏览器基线移除 legacy 变体；WASM 守卫同时观察 instantiate/instantiateStreaming， 并在每次页面加载时固定 DPR，避免开发服务器重载丢失测试环境设置。</li></ul><p>本项只执行定向回归；T21 的公共 API/完整示例文档迁移、T22 的全量单测与多浏览器 验收、T23 性能资源检查、T24 最终审计仍按原任务执行。本次未把全量回归标记为通过。 当前验证环境为 Node 22.22.1，低于 package.json 声明的 Node 24.13.1； 构建和包消费检查通过，但目标 Node 版本验收仍应在最终回归环境执行。</p>`,13)])])}const u=a(n,[["render",l]]);export{k as __pageData,u as default};
